import {
    columnHasValue
} from "../../../grids/grid_core/columns_controller/columns_controller_utils";
import gridCoreUtils from "../m_utils";
const INVISIBLE_CLASS = "dx-state-invisible";
export const getCellText = (column, displayValue) => columnHasValue(column) ? gridCoreUtils.formatValue(displayValue, column) : "";
export const getMaxHorizontalScrollOffset = container => container ? Math.round(container.scrollWidth - container.clientWidth) : 0;
export const isSameColumnLayout = (renderedColumns, columns) => renderedColumns.length === columns.length && renderedColumns.every((column, index) => column.index === columns[index].index && column.command === columns[index].command);
export const isRowElementVisible = rowElement => "none" !== rowElement.style.display && !rowElement.classList.contains(INVISIBLE_CLASS);
export const insertRowElement = ($newRow, $rows, rowIndex, $table) => {
    const $row = $rows.eq(rowIndex);
    if ($row.length) {
        $newRow.insertBefore($row)
    } else if ($rows.length) {
        $newRow.insertAfter($rows.last())
    } else if ($table) {
        $newRow.prependTo($newRow.is("tbody") ? $table : $table.children("tbody"))
    }
};
